{
  "name": "pwa2apk",
  "version": "0.1.0",
  "description": "Convert PWA manifest URLs to native-looking Android APKs using WebView — no Chrome TWA banners",
  "main": "src/index.js",
  "bin": {
    "pwa2apk": "src/cli.js"
  },
  "scripts": {
    "test": "node src/cli.js --help"
  },
  "keywords": ["pwa", "apk", "android", "webview"],
  "license": "UNLICENSED",
  "private": true,
  "engines": {
    "node": ">=18"
  }
}

'use strict';

const fs = require('fs');
const path = require('path');
const { execSync, execFileSync } = require('child_process');
const crypto = require('crypto');
const https = require('https');
const http = require('http');
const { URL } = require('url');

// ── Helpers ─────────────────────────────────────────────────────────────────

function fetch(url) {
  return new Promise((resolve, reject) => {
    const mod = url.startsWith('https') ? https : http;
    mod.get(url, { headers: { 'User-Agent': 'pwa2apk/0.1' } }, (res) => {
      if (res.statusCode >= 300 && res.statusCode < 400 && res.headers.location) {
        return resolve(fetch(res.headers.location));
      }
      if (res.statusCode !== 200) {
        return reject(new Error(`HTTP ${res.statusCode} for ${url}`));
      }
      const chunks = [];
      res.on('data', (c) => chunks.push(c));
      res.on('end', () => resolve(Buffer.concat(chunks)));
      res.on('error', reject);
    }).on('error', reject);
  });
}

function fetchJson(url) {
  return fetch(url).then((buf) => JSON.parse(buf.toString()));
}

function derivePackageName(manifestUrl) {
  const { hostname } = new URL(manifestUrl);
  // com.example.foo from foo.example.com
  const parts = hostname.split('.').reverse().filter(Boolean);
  return parts
    .map((p) => p.replace(/[^a-zA-Z0-9]/g, '_'))
    .map((p) => (/^\d/.test(p) ? '_' + p : p))
    .join('.');
}

function escapeXml(s) {
  return s
    .replace(/&/g, '&amp;')
    .replace(/</g, '&lt;')
    .replace(/>/g, '&gt;')
    .replace(/"/g, '&quot;')
    .replace(/'/g, '&apos;');
}

function findJavaHome() {
  if (process.env.JAVA_HOME) return process.env.JAVA_HOME;
  for (const p of [
    '/usr/lib/jvm/java-17-openjdk-amd64',
    '/usr/lib/jvm/java-21-openjdk-amd64',
    '/opt/homebrew/opt/openjdk@17/libexec/openjdk.jdk/Contents/Home',
    '/opt/homebrew/opt/openjdk@21/libexec/openjdk.jdk/Contents/Home',
  ]) {
    if (fs.existsSync(p)) return p;
  }
  throw new Error('JAVA_HOME not set and no JDK found');
}

function findAndroidSdk() {
  for (const env of ['ANDROID_HOME', 'ANDROID_SDK_ROOT']) {
    if (process.env[env] && fs.existsSync(process.env[env])) return process.env[env];
  }
  const cuaSdk = path.join(process.env.HOME || '~', '.cua', 'android-sdk');
  if (fs.existsSync(cuaSdk)) return cuaSdk;
  throw new Error(
    'Android SDK not found. Set ANDROID_HOME or install via cua-sandbox.'
  );
}

// ── Icon handling ───────────────────────────────────────────────────────────

async function downloadIcon(iconUrl, destPath, size) {
  const buf = await fetch(iconUrl);
  // If it's an SVG, we need to convert to PNG. Try sharp, fall back to writing
  // a placeholder PNG.
  if (
    iconUrl.endsWith('.svg') ||
    buf.slice(0, 5).toString().includes('<svg') ||
    buf.slice(0, 5).toString().includes('<?xml')
  ) {
    try {
      // Try using sharp for SVG -> PNG conversion
      const sharp = require('sharp');
      const png = await sharp(buf).resize(size, size).png().toBuffer();
      fs.writeFileSync(destPath, png);
      return;
    } catch (_) {
      // sharp not available — generate a simple colored PNG placeholder
      fs.writeFileSync(destPath, createPlaceholderPng(size));
      return;
    }
  }
  fs.writeFileSync(destPath, buf);
}

function createPlaceholderPng(size) {
  // Minimal valid 1x1 PNG scaled up won't work, but we can use Android's
  // adaptive icon XML instead. Write a 1-pixel PNG as fallback.
  // In practice, the Gradle build will use the adaptive icon XML.
  const PNG_1x1 = Buffer.from(
    'iVBORw0KGgoAAAANSUhEUgAAAAEAAAABCAYAAAAfFcSJAAAADUlEQVR42mNk+M9QDwADhgGAWjR9awAAAABJRU5ErkJggg==',
    'base64'
  );
  return PNG_1x1;
}

// ── Main build function ─────────────────────────────────────────────────────

async function buildApk(opts) {
  const {
    manifestUrl,
    fetchUrl,
    keystoreAlias = 'android',
    keystorePassword = 'android',
  } = opts;

  const resolvedFetchUrl = fetchUrl || manifestUrl;
  console.log(`Fetching manifest: ${resolvedFetchUrl}`);
  const manifest = await fetchJson(resolvedFetchUrl);

  const appName = manifest.name || manifest.short_name || 'PWA App';
  const shortName = manifest.short_name || manifest.name || 'PWA';
  const startUrl = manifest.start_url || '/';
  const display = manifest.display || 'standalone';
  const orientation = manifest.orientation || 'portrait';
  const bgColor = manifest.background_color || '#FFFFFF';
  const themeColor = manifest.theme_color || '#000000';
  const icons = manifest.icons || [];

  const packageName =
    opts.packageName || derivePackageName(manifestUrl);

  // Resolve absolute start URL
  const base = new URL(manifestUrl);
  const absoluteStartUrl = new URL(startUrl, base).toString();
  // Origin for scope checking
  const origin = `${base.protocol}//${base.host}`;

  console.log(`App:     ${appName}`);
  console.log(`Package: ${packageName}`);
  console.log(`Start:   ${absoluteStartUrl}`);

  // ── Build directory ─────────────────────────────────────────────────────
  const cacheKey = crypto
    .createHash('sha256')
    .update(`${manifestUrl}|${packageName}`)
    .digest('hex')
    .slice(0, 12);
  const buildDir = path.join(
    process.env.HOME || '/tmp',
    '.cua',
    'pwa2apk-cache',
    cacheKey
  );
  fs.mkdirSync(buildDir, { recursive: true });

  // ── Copy template ───────────────────────────────────────────────────────
  const templateDir = path.join(__dirname, '..', 'template');
  copyDirSync(templateDir, buildDir);

  // ── Generate source files from template variables ───────────────────────
  const javaDir = path.join(
    buildDir,
    'app',
    'src',
    'main',
    'java',
    ...packageName.split('.')
  );
  fs.mkdirSync(javaDir, { recursive: true });

  // MainActivity.java
  fs.writeFileSync(
    path.join(javaDir, 'MainActivity.java'),
    generateMainActivity(packageName, absoluteStartUrl, origin, themeColor)
  );

  // SplashActivity.java
  fs.writeFileSync(
    path.join(javaDir, 'SplashActivity.java'),
    generateSplashActivity(packageName)
  );

  // AndroidManifest.xml
  fs.writeFileSync(
    path.join(buildDir, 'app', 'src', 'main', 'AndroidManifest.xml'),
    generateManifest(packageName, appName, orientation, base.host)
  );

  // res/values — not in the template, must be created before writing
  fs.mkdirSync(path.join(buildDir, 'app', 'src', 'main', 'res', 'values'), { recursive: true });

  // strings.xml
  fs.writeFileSync(
    path.join(buildDir, 'app', 'src', 'main', 'res', 'values', 'strings.xml'),
    `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <string name="app_name">${escapeXml(shortName)}</string>
    <string name="app_name_full">${escapeXml(appName)}</string>
</resources>
`
  );

  // colors.xml
  fs.writeFileSync(
    path.join(buildDir, 'app', 'src', 'main', 'res', 'values', 'colors.xml'),
    `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <color name="theme_color">${themeColor}</color>
    <color name="background_color">${bgColor}</color>
    <color name="status_bar">${themeColor}</color>
</resources>
`
  );

  // styles.xml
  fs.writeFileSync(
    path.join(buildDir, 'app', 'src', 'main', 'res', 'values', 'styles.xml'),
    `<?xml version="1.0" encoding="utf-8"?>
<resources>
    <style name="AppTheme" parent="android:Theme.Material.Light.NoActionBar">
        <item name="android:statusBarColor">@color/status_bar</item>
        <item name="android:navigationBarColor">@color/theme_color</item>
        <item name="android:windowBackground">@color/background_color</item>
    </style>
    <style name="SplashTheme" parent="android:Theme.Material.Light.NoActionBar">
        <item name="android:statusBarColor">@color/theme_color</item>
        <item name="android:navigationBarColor">@color/theme_color</item>
        <item name="android:windowBackground">@color/background_color</item>
    </style>
</resources>
`
  );

  // ── Download icons ──────────────────────────────────────────────────────
  const iconDir = path.join(buildDir, 'app', 'src', 'main', 'res', 'mipmap-xxxhdpi');
  fs.mkdirSync(iconDir, { recursive: true });

  // Find best icon (prefer 192px PNG, fall back to largest)
  const pngIcons = icons.filter(
    (i) => i.type === 'image/png' || (i.src && i.src.endsWith('.png'))
  );
  const svgIcons = icons.filter(
    (i) => i.type === 'image/svg+xml' || (i.src && i.src.endsWith('.svg'))
  );
  // Prefer SVG (always available, scales perfectly) over PNG
  const bestIcon =
    svgIcons.find((i) => i.sizes && i.sizes.includes('192')) ||
    svgIcons[0] ||
    pngIcons.find((i) => i.sizes && i.sizes.includes('192')) ||
    pngIcons[0] ||
    icons[0];

  if (bestIcon) {
    const iconUrl = new URL(bestIcon.src, base).toString();
    console.log(`Icon:    ${iconUrl}`);
    try {
      await downloadIcon(iconUrl, path.join(iconDir, 'ic_launcher.png'), 192);
    } catch (err) {
      console.warn(`Warning: failed to download icon: ${err.message}`);
      fs.writeFileSync(path.join(iconDir, 'ic_launcher.png'), createPlaceholderPng(192));
    }
  } else {
    fs.writeFileSync(path.join(iconDir, 'ic_launcher.png'), createPlaceholderPng(192));
  }

  // ── build.gradle (app) ────────────────────────────────────────────────
  fs.writeFileSync(
    path.join(buildDir, 'app', 'build.gradle'),
    generateAppBuildGradle(packageName)
  );

  // ── Keystore ──────────────────────────────────────────────────────────
  const javaHome = findJavaHome();
  const keytool = path.join(javaHome, 'bin', 'keytool');
  let keystorePath = opts.keystore;
  if (!keystorePath) {
    keystorePath = path.join(buildDir, 'debug.keystore');
    if (!fs.existsSync(keystorePath)) {
      console.log('Generating debug keystore...');
      execFileSync(keytool, [
        '-genkeypair', '-v',
        '-keystore', keystorePath,
        '-alias', keystoreAlias,
        '-keyalg', 'RSA', '-keysize', '2048',
        '-validity', '10000',
        '-storepass', keystorePassword,
        '-keypass', keystorePassword,
        '-dname', 'CN=pwa2apk, OU=Dev, O=CUA, L=SF, S=CA, C=US',
      ], { timeout: 30000 });
    }
  }

  // Write signing config
  fs.writeFileSync(
    path.join(buildDir, 'keystore.properties'),
    `storeFile=${keystorePath}
storePassword=${keystorePassword}
keyAlias=${keystoreAlias}
keyPassword=${keystorePassword}
`
  );

  // ── Extract fingerprint ───────────────────────────────────────────────
  let fingerprint = '';
  try {
    const fpOut = execFileSync(
      keytool,
      ['-list', '-v', '-keystore', keystorePath, '-alias', keystoreAlias, '-storepass', keystorePassword],
      { timeout: 15000, encoding: 'utf-8' }
    );
    const match = fpOut.match(/SHA256:\s*([\dA-F:]+)/i);
    if (match) fingerprint = match[1];
  } catch (_) {}

  // ── local.properties ──────────────────────────────────────────────────
  const sdkDir = findAndroidSdk();
  fs.writeFileSync(
    path.join(buildDir, 'local.properties'),
    `sdk.dir=${sdkDir}\n`
  );

  // ── Gradle build ──────────────────────────────────────────────────────
  console.log('Building APK...');
  const gradlew = path.join(buildDir, 'gradlew');
  if (fs.existsSync(gradlew)) {
    fs.chmodSync(gradlew, 0o755);
  }

  const env = {
    ...process.env,
    JAVA_HOME: javaHome,
    ANDROID_HOME: sdkDir,
    ANDROID_SDK_ROOT: sdkDir,
  };

  execSync('./gradlew assembleRelease --no-daemon -q 2>&1', {
    cwd: buildDir,
    env,
    timeout: 300000,
    stdio: 'inherit',
  });

  // Find the APK
  const apkDir = path.join(buildDir, 'app', 'build', 'outputs', 'apk', 'release');
  const apks = fs.readdirSync(apkDir).filter((f) => f.endsWith('.apk'));
  if (apks.length === 0) {
    throw new Error(`No APK found in ${apkDir}`);
  }

  const builtApk = path.join(apkDir, apks[0]);
  const outputPath = opts.outputPath || path.join(process.cwd(), `${packageName}.apk`);
  fs.copyFileSync(builtApk, outputPath);

  return { apkPath: outputPath, packageName, fingerprint };
}

// ── Template generators ─────────────────────────────────────────────────────

function generateMainActivity(pkg, startUrl, origin, themeColor) {
  return `package ${pkg};

import android.app.Activity;
import android.graphics.Color;
import android.os.Build;
import android.os.Bundle;
import android.view.View;
import android.view.ViewGroup;
import android.view.Window;
import android.view.WindowManager;
import android.webkit.CookieManager;
import android.webkit.WebChromeClient;
import android.webkit.WebResourceRequest;
import android.webkit.WebSettings;
import android.webkit.WebView;
import android.webkit.WebViewClient;
import android.widget.FrameLayout;

public class MainActivity extends Activity {
    private WebView webView;
    private static final String START_URL = "${startUrl}";
    private static final String ORIGIN = "${origin}";

    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        requestWindowFeature(Window.FEATURE_NO_TITLE);

        // Draw behind the status bar with a colored status bar
        getWindow().getDecorView().setSystemUiVisibility(
            View.SYSTEM_UI_FLAG_LAYOUT_STABLE
            | View.SYSTEM_UI_FLAG_LAYOUT_FULLSCREEN
        );
        getWindow().setStatusBarColor(Color.parseColor("${themeColor}"));

        // Wrap WebView in a FrameLayout with fitsSystemWindows so the
        // content starts below the status bar, not under it.
        FrameLayout wrapper = new FrameLayout(this);
        wrapper.setFitsSystemWindows(true);

        webView = new WebView(this);
        wrapper.addView(webView, new FrameLayout.LayoutParams(
            ViewGroup.LayoutParams.MATCH_PARENT,
            ViewGroup.LayoutParams.MATCH_PARENT));
        setContentView(wrapper);

        WebSettings settings = webView.getSettings();
        settings.setJavaScriptEnabled(true);
        settings.setDomStorageEnabled(true);
        settings.setDatabaseEnabled(true);
        settings.setCacheMode(WebSettings.LOAD_DEFAULT);
        settings.setMediaPlaybackRequiresUserGesture(false);
        settings.setMixedContentMode(WebSettings.MIXED_CONTENT_COMPATIBILITY_MODE);
        settings.setAllowFileAccess(false);
        settings.setUserAgentString(settings.getUserAgentString() + " pwa2apk");

        // Enable Service Workers (API 24+)
        if (Build.VERSION.SDK_INT >= Build.VERSION_CODES.O) {
            settings.setSafeBrowsingEnabled(false);
        }

        // Cookies
        CookieManager.getInstance().setAcceptCookie(true);
        CookieManager.getInstance().setAcceptThirdPartyCookies(webView, true);

        webView.setWebViewClient(new WebViewClient() {
            @Override
            public boolean shouldOverrideUrlLoading(WebView view, WebResourceRequest request) {
                String url = request.getUrl().toString();
                // Stay in-app for same-origin navigation
                if (url.startsWith(ORIGIN)) {
                    return false;
                }
                // Open external links in browser
                try {
                    android.content.Intent intent = new android.content.Intent(
                        android.content.Intent.ACTION_VIEW, request.getUrl());
                    startActivity(intent);
                } catch (Exception e) {
                    // fall through to WebView
                    return false;
                }
                return true;
            }
        });

        webView.setWebChromeClient(new WebChromeClient());

        if (savedInstanceState != null) {
            webView.restoreState(savedInstanceState);
        } else {
            android.net.Uri intentUri = getIntent() != null ? getIntent().getData() : null;
            String loadUrl = (intentUri != null) ? intentUri.toString() : START_URL;
            webView.loadUrl(loadUrl);
        }
    }

    @Override
    public void onBackPressed() {
        if (webView != null && webView.canGoBack()) {
            webView.goBack();
        } else {
            super.onBackPressed();
        }
    }

    @Override
    protected void onSaveInstanceState(Bundle outState) {
        super.onSaveInstanceState(outState);
        if (webView != null) webView.saveState(outState);
    }

    @Override
    protected void onResume() {
        super.onResume();
        if (webView != null) webView.onResume();
    }

    @Override
    protected void onPause() {
        if (webView != null) webView.onPause();
        super.onPause();
    }

    @Override
    protected void onDestroy() {
        if (webView != null) {
            webView.destroy();
        }
        super.onDestroy();
    }
}
`;
}

function generateSplashActivity(pkg) {
  return `package ${pkg};

import android.app.Activity;
import android.content.Intent;
import android.os.Bundle;
import android.os.Handler;

public class SplashActivity extends Activity {
    @Override
    protected void onCreate(Bundle savedInstanceState) {
        super.onCreate(savedInstanceState);
        // Brief splash, then launch main
        new Handler().postDelayed(() -> {
            startActivity(new Intent(this, MainActivity.class));
            finish();
        }, 200);
    }
}
`;
}

function generateManifest(pkg, appName, orientation, host) {
  const orientationAttr = orientation === 'any' ? 'unspecified' : orientation;
  return `<?xml version="1.0" encoding="utf-8"?>
<manifest xmlns:android="http://schemas.android.com/apk/res/android"
    package="${pkg}">

    <uses-permission android:name="android.permission.INTERNET" />
    <uses-permission android:name="android.permission.ACCESS_NETWORK_STATE" />

    <application
        android:label="@string/app_name"
        android:icon="@mipmap/ic_launcher"
        android:theme="@style/AppTheme"
        android:usesCleartextTraffic="true"
        android:hardwareAccelerated="true"
        android:supportsRtl="true">

        <activity
            android:name=".SplashActivity"
            android:theme="@style/SplashTheme"
            android:exported="true">
            <intent-filter>
                <action android:name="android.intent.action.MAIN" />
                <category android:name="android.intent.category.LAUNCHER" />
            </intent-filter>
        </activity>

        <activity
            android:name=".MainActivity"
            android:screenOrientation="${orientationAttr}"
            android:configChanges="orientation|keyboardHidden|screenSize|smallestScreenSize"
            android:exported="true">
            <intent-filter>
                <action android:name="android.intent.action.VIEW" />
                <category android:name="android.intent.category.DEFAULT" />
                <category android:name="android.intent.category.BROWSABLE" />
                <data android:scheme="https" android:host="${host}" />
                <data android:scheme="http" android:host="${host}" />
            </intent-filter>
        </activity>
    </application>
</manifest>
`;
}

function generateAppBuildGradle(packageName) {
  return `plugins {
    id 'com.android.application'
}

def keystorePropertiesFile = rootProject.file("keystore.properties")
def keystoreProperties = new Properties()
if (keystorePropertiesFile.exists()) {
    keystoreProperties.load(new FileInputStream(keystorePropertiesFile))
}

android {
    namespace '${packageName}'
    compileSdk 34

    defaultConfig {
        applicationId "${packageName}"
        minSdk 24
        targetSdk 34
        versionCode 1
        versionName "1.0"
    }

    signingConfigs {
        release {
            storeFile file(keystoreProperties['storeFile'] ?: 'debug.keystore')
            storePassword keystoreProperties['storePassword'] ?: 'android'
            keyAlias keystoreProperties['keyAlias'] ?: 'android'
            keyPassword keystoreProperties['keyPassword'] ?: 'android'
        }
    }

    buildTypes {
        release {
            minifyEnabled false
            signingConfig signingConfigs.release
        }
    }

    compileOptions {
        sourceCompatibility JavaVersion.VERSION_17
        targetCompatibility JavaVersion.VERSION_17
    }
}

dependencies {
}
`;
}

// ── File utils ──────────────────────────────────────────────────────────────

function copyDirSync(src, dest) {
  if (!fs.existsSync(src)) return;
  fs.mkdirSync(dest, { recursive: true });
  for (const entry of fs.readdirSync(src, { withFileTypes: true })) {
    const srcPath = path.join(src, entry.name);
    const destPath = path.join(dest, entry.name);
    if (entry.isDirectory()) {
      copyDirSync(srcPath, destPath);
    } else {
      fs.copyFileSync(srcPath, destPath);
    }
  }
}

module.exports = { buildApk };

#!/usr/bin/env node
'use strict';

const { buildApk } = require('./index');

const args = process.argv.slice(2);

if (args.includes('--help') || args.includes('-h') || args.length === 0) {
  console.log(`
pwa2apk — Convert a PWA manifest to a native Android APK (WebView, no Chrome banners)

Usage:
  pwa2apk <manifest-url> [options]

Options:
  --package <id>            Android package name (default: derived from manifest URL)
  --keystore <path>         Path to signing keystore (default: auto-generated debug keystore)
  --keystore-alias <alias>  Keystore alias (default: "android")
  --keystore-password <pw>  Keystore password (default: "android")
  --output <path>           Output APK path (default: ./<package>.apk)
  --fetch-url <url>         URL to fetch manifest from (if different from manifest-url)
  --help, -h                Show this help
`);
  process.exit(0);
}

function getOpt(flag) {
  const idx = args.indexOf(flag);
  if (idx === -1 || idx + 1 >= args.length) return undefined;
  return args[idx + 1];
}

const manifestUrl = args.find((a) => !a.startsWith('--'));
if (!manifestUrl) {
  console.error('Error: manifest URL is required');
  process.exit(1);
}

(async () => {
  try {
    const result = await buildApk({
      manifestUrl,
      packageName: getOpt('--package'),
      keystore: getOpt('--keystore'),
      keystoreAlias: getOpt('--keystore-alias') || 'android',
      keystorePassword: getOpt('--keystore-password') || 'android',
      outputPath: getOpt('--output'),
      fetchUrl: getOpt('--fetch-url'),
    });
    console.log(`\nAPK built: ${result.apkPath}`);
    console.log(`Package:   ${result.packageName}`);
    if (result.fingerprint) {
      console.log(`SHA-256:   ${result.fingerprint}`);
    }
  } catch (err) {
    console.error(`Error: ${err.message}`);
    process.exit(1);
  }
})();
